<?php
class Reporte_reservas_model extends CI_Model{
 public function usuario_tiene_rol($u,$r){return !empty($this->db->query("SELECT 1 x FROM usuario u INNER JOIN rol_usuario ru ON ru.tipousuario_id=u.tipousuario_id WHERE u.usuario_id=? AND ru.rol_id=? AND ru.rolusuario_asignado=1 LIMIT 1",array((int)$u,(int)$r))->row_array());}
 public function rutas(){return $this->db->query("SELECT ruta_id,ruta_nombre FROM ruta ORDER BY ruta_nombre")->result_array();}
 private function where($f,&$p){$w="vp.venta_fecha BETWEEN ? AND ? AND vp.venta_codigoreserva IS NOT NULL AND vp.venta_codigoreserva<>'' AND vp.venta_codigoreserva<>'0'";$p=array($f['desde'],$f['hasta']);if($f['ruta_id']>0){$w.=" AND v.ruta_id=?";$p[]=$f['ruta_id'];}return $w;}
 private function clasificacion(){return "CASE WHEN vp.reserva_usuario_confirma_id IS NOT NULL OR EXISTS(SELECT 1 FROM pasaje pc WHERE pc.venta_id=vp.venta_id AND pc.estado_id=54) THEN 'CONFIRMADA' WHEN vp.reserva_liberada_at IS NOT NULL AND (UPPER(COALESCE(vp.reserva_motivo_liberacion,'')) LIKE '%VENC%' OR EXISTS(SELECT 1 FROM reserva_evento re WHERE re.venta_id=vp.venta_id AND re.evento_tipo='LIBERACION' AND UPPER(COALESCE(re.evento_motivo,'')) LIKE '%VENC%')) THEN 'VENCIDA' WHEN vp.reserva_liberada_at IS NOT NULL OR vp.estado_id=3 THEN 'CANCELADA' WHEN vp.estado_id=52 THEN 'PENDIENTE' ELSE 'PENDIENTE' END";}
 public function resumen($f){$p=array();$w=$this->where($f,$p);$c=$this->clasificacion();$sql="SELECT COUNT(*) realizadas,SUM(CASE WHEN clasificacion='CONFIRMADA' THEN 1 ELSE 0 END) confirmadas,SUM(CASE WHEN clasificacion='VENCIDA' THEN 1 ELSE 0 END) vencidas,SUM(CASE WHEN clasificacion='CANCELADA' THEN 1 ELSE 0 END) canceladas,SUM(CASE WHEN clasificacion='PENDIENTE' THEN 1 ELSE 0 END) pendientes FROM (SELECT vp.venta_id,$c clasificacion FROM venta_pasaje vp LEFT JOIN viaje v ON v.viaje_id=vp.viaje_id WHERE $w) q";return $this->db->query($sql,$p)->row_array();}
 public function detalle($f){$p=array();$w=$this->where($f,$p);$c=$this->clasificacion();$having="";if(in_array($f['estado'],array('CONFIRMADA','VENCIDA','CANCELADA','PENDIENTE'),true)){$having=" HAVING clasificacion=?";$p[]=$f['estado'];}$sql="SELECT vp.venta_id,vp.venta_codigoreserva codigo,CONCAT(vp.venta_fecha,' ',vp.venta_hora) fecha_reserva,CONCAT(COALESCE(vp.venta_fechareserva,''),' ',COALESCE(vp.venta_horareserva,'')) limite,COALESCE(r.ruta_nombre,CONCAT_WS(' - ',r.inicio_ruta,r.fin_ruta)) ruta,(SELECT COUNT(*) FROM pasaje pp WHERE pp.venta_id=vp.venta_id) pasajeros,COALESCE(vp.venta_acuentareserva,0) acuenta,$c clasificacion,COALESCE(vp.reserva_motivo_liberacion,'') motivo FROM venta_pasaje vp LEFT JOIN viaje v ON v.viaje_id=vp.viaje_id LEFT JOIN ruta r ON r.ruta_id=v.ruta_id WHERE $w $having ORDER BY vp.venta_fecha DESC,vp.venta_hora DESC";return $this->db->query($sql,$p)->result_array();}
}
